# 테마 1 캐릭터 정의 (3D 점) — 세검 · 대검 · 애저 워든. figure.py 퍼펫으로 그린다.
from figure import *

def hair_strand(F, root, pts, w0, fill=INK, bias=0.0, sw=1.4):
    F.ribbon([root] + pts, [w0] + [w0 * (0.85 - 0.75 * i / max(1, len(pts) - 1)) for i in range(len(pts) - 1)] + [0.0], fill, sw=sw, shade=False, bias=bias, n=5)

def face(F, hc, tilt=0.0, accent=None, accentY=-0.035, wide=0.064, brows=False):
    x0, y0, z0 = hc
    pts = [(x0 - wide, y0 + 0.05, z0 + 0.05), (x0 - wide - 0.004, y0, z0 + 0.06), (x0 - wide + 0.012, y0 - 0.055, z0 + 0.065), (x0 - 0.02, y0 - 0.095, z0 + 0.08),
           (x0 + 0.002, y0 - 0.105, z0 + 0.085), (x0 + 0.024, y0 - 0.092, z0 + 0.078), (x0 + wide - 0.012, y0 - 0.05, z0 + 0.06), (x0 + wide, y0 + 0.005, z0 + 0.055), (x0 + wide - 0.004, y0 + 0.05, z0 + 0.045)]
    sh = [(x0 + 0.01, y0 - 0.1, z0 + 0.082), (x0 + 0.024, y0 - 0.092, z0 + 0.078), (x0 + wide - 0.012, y0 - 0.05, z0 + 0.06), (x0 + wide, y0 + 0.005, z0 + 0.055), (x0 + wide - 0.004, y0 + 0.05, z0 + 0.045), (x0 + 0.035, y0 + 0.0, z0 + 0.07), (x0 + 0.03, y0 - 0.06, z0 + 0.075)]
    F.blob(pts, SKIN, 1.5, bias=0.05, shade_pts=sh, sh=SKSH)
    e = 0.028
    F.line([(x0 - 0.045, y0 - 0.004, z0 + 0.08), (x0 - e + 0.002, y0 - 0.008, z0 + 0.085), (x0 - 0.01, y0 - 0.006, z0 + 0.088)], 2.0, INK, 0.07)
    F.line([(x0 + 0.01, y0 - 0.006, z0 + 0.088), (x0 + e, y0 - 0.008, z0 + 0.085), (x0 + 0.045, y0 - 0.004, z0 + 0.075)], 2.0, INK, 0.07)
    if brows:
        F.line([(x0 - 0.05, y0 + 0.022, z0 + 0.075), (x0 - 0.012, y0 + 0.012, z0 + 0.088)], 1.6, INK, 0.07); F.line([(x0 + 0.012, y0 + 0.012, z0 + 0.088), (x0 + 0.05, y0 + 0.022, z0 + 0.07)], 1.6, INK, 0.07)
    if accent:
        F.line([(x0 + 0.008, y0 + accentY, z0 + 0.088), (x0 + 0.05, y0 + accentY + 0.004, z0 + 0.072)], 1.7, accent, 0.075)
        if accent == RED: F.line([(x0 - 0.05, y0 + accentY + 0.004, z0 + 0.075), (x0 - 0.008, y0 + accentY, z0 + 0.088)], 1.7, accent, 0.075)

# --------------------------------------------------------------------------- 세검 (청)
def rapier(F):
    J, h = body_joints(1.80, 7.6, 0.162, 0.125, 'R')
    hc = (0.012, 1.655, 0.0)
    # 뒷머리 (어깨 아래 · 바깥으로 튐) — 가장 뒤
    for (dx, y1, x2, y2, w) in [(-0.07, 1.62, -0.19, 1.30, 0.10), (-0.03, 1.58, -0.12, 1.24, 0.11), (0.02, 1.58, 0.05, 1.22, 0.12), (0.06, 1.6, 0.17, 1.28, 0.11), (0.09, 1.64, 0.24, 1.38, 0.08)]:
        hair_strand(F, (hc[0] + dx * 0.6, 1.76, -0.07), [(hc[0] + dx * 1.4, y1, -0.13), (x2 * 0.8, (y1 + y2) / 2, -0.16), (x2, y2, -0.17)], w, bias=-0.6)
    # 코트 뒷자락 (다리 뒤 · 끝 갈라짐 · 바람에 오른쪽으로)
    F.blob([J['shL'], (0.19, 1.2, -0.08), (0.22, 0.9, -0.09), (0.31, 0.5, -0.11), (0.33, 0.30, -0.12), (0.22, 0.36, -0.12), (0.12, 0.26, -0.12), (0.01, 0.34, -0.12), (-0.10, 0.27, -0.12), (-0.18, 0.36, -0.11), (-0.22, 0.5, -0.1), (-0.2, 0.9, -0.08), (-0.18, 1.2, -0.07), J['shR']], INK, 2.2, bias=-0.5, smooth=False)
    # 다리 (검정 하의) + 뾰족한 구두
    for s in 'RL':
        F.ribbon([J['hip' + s], J['kn' + s]], [0.115, 0.07], INK, 2.0, bias=-0.05)
        F.ribbon([J['kn' + s], lerp(J['kn' + s], J['an' + s], 0.35), J['an' + s]], [0.07, 0.068, 0.045], INK, 2.0, bias=-0.05)
        F.ribbon([J['an' + s], J['toe' + s]], [0.06, 0.004], INK, 1.8, bias=0.0)
    # 셔츠 몸통 (흰 · 허리 잘록 · 골반)
    F.blob([(-0.045, 1.53, 0.04), J['shR'], (-0.135, 1.36, 0.03), (-0.1, 1.2, 0.06), (-0.095, 1.08, 0.06), (-0.13, 0.97, 0.05), (-0.03, 0.9, 0.08), (0.05, 0.9, 0.08), (0.15, 0.97, 0.05), (0.115, 1.08, 0.06), (0.12, 1.2, 0.06), (0.14, 1.36, 0.03), J['shL'], (0.045, 1.53, 0.04)],
           PAPER, 1.6, bias=0.02, shade_pts=[(0.02, 1.5, 0.08), (0.06, 1.36, 0.09), (0.08, 1.2, 0.09), (0.07, 1.06, 0.09), (0.1, 0.96, 0.07), (0.15, 0.97, 0.05), (0.115, 1.08, 0.06), (0.12, 1.2, 0.06), (0.14, 1.36, 0.03), J['shL']])
    F.line([(-0.03, 1.3, 0.1), (-0.05, 1.18, 0.1)], 0.9); F.line([(0.04, 1.22, 0.1), (0.06, 1.08, 0.1)], 0.9)
    # 코트 앞판 (소매 없는 검정 롱코트 · 열림 · 흰 분리선)
    F.blob([(0.045, 1.52, 0.07), J['shL'], (0.18, 1.3, 0.05), (0.16, 1.07, 0.09), (0.2, 0.7, 0.12), (0.27, 0.36, 0.12), (0.19, 0.31, 0.14), (0.12, 0.38, 0.15), (0.075, 0.32, 0.16), (0.06, 0.88, 0.14), (0.07, 1.1, 0.12), (0.055, 1.36, 0.11)], INK, 2.2, bias=0.15, smooth=False)
    F.blob([(-0.045, 1.52, 0.07), J['shR'], (-0.17, 1.3, 0.05), (-0.15, 1.07, 0.09), (-0.2, 0.72, 0.12), (-0.24, 0.38, 0.13), (-0.16, 0.34, 0.15), (-0.11, 0.28, 0.15), (-0.06, 0.36, 0.16), (-0.045, 0.88, 0.14), (-0.06, 1.1, 0.12), (-0.05, 1.36, 0.11)], INK, 2.2, bias=0.15, smooth=False)
    F.line([(0.055, 1.36, 0.115), (0.07, 1.1, 0.125), (0.06, 0.88, 0.145), (0.075, 0.34, 0.165)], 1.1, PAPER, 0.17)
    F.line([(-0.05, 1.36, 0.115), (-0.06, 1.1, 0.125), (-0.045, 0.88, 0.145), (-0.06, 0.38, 0.165)], 1.1, PAPER, 0.17)
    # 흰 세운 깃 + 벨트 + 파랑 장식 끈
    F.blob([(-0.07, 1.5, 0.03), (-0.06, 1.6, 0.04), (0.0, 1.565, 0.08), (0.06, 1.6, 0.04), (0.07, 1.5, 0.03), (0.0, 1.46, 0.1)], PAPER, 1.6, bias=0.2, smooth=False, shade_pts=[(0.0, 1.565, 0.08), (0.06, 1.6, 0.04), (0.07, 1.5, 0.03), (0.0, 1.46, 0.1)], sh=SH2)
    F.ribbon([(-0.1, 0.99, 0.09), (0.0, 0.98, 0.11), (0.11, 0.99, 0.09)], [0.035, 0.035, 0.035], INK, 1.4, shade=False, bias=0.18)
    F.ribbon([(0.1, 0.98, 0.1), (0.13, 0.86, 0.12), (0.12, 0.72, 0.13)], [0.03, 0.025, 0.008], BLUE, 1.2, shade=False, bias=0.2)
    F.ribbon([(0.11, 0.98, 0.1), (0.155, 0.84, 0.11), (0.165, 0.66, 0.11)], [0.025, 0.02, 0.006], BLUE, 1.2, shade=False, bias=0.2)
    # 칼집 (검정 · 파랑 감김) — 왼허리에서 뒤로
    F.ribbon([(0.13, 1.0, 0.06), (0.3, 0.72, -0.1), (0.46, 0.46, -0.25)], [0.04, 0.038, 0.034], INK, 1.8, shade=False, bias=-0.1)
    # 팔: 넓은 흰 셔츠 소매 + 검정 장갑 (긴 손가락) — 오른팔은 세검을 뒤로 비스듬히 · 왼팔은 칼집 위에
    elR, wrR, haR = (-0.23, 1.17, -0.02), (-0.33, 0.95, 0.05), (-0.37, 0.86, 0.08)
    F.ribbon([J['shR'], elR, wrR], [0.1, 0.085, 0.1], PAPER, 1.7, bias=0.05)
    F.line([(-0.2, 1.28, 0.03), (-0.235, 1.22, 0.03)], 0.9, INK, 0.1); F.line([(-0.28, 1.06, 0.06), (-0.3, 1.0, 0.07)], 0.9, INK, 0.1)
    F.ribbon([wrR, haR], [0.05, 0.048], INK, 1.6, bias=0.06); fingers(F, haR, (-0.2, -1.0, 0.25), 4, 0.07, 0.01, INK, 0.07)
    elL, wrL, haL = (0.235, 1.15, -0.04), (0.2, 0.97, 0.1), (0.15, 0.92, 0.13)
    F.ribbon([J['shL'], elL, wrL], [0.1, 0.085, 0.1], PAPER, 1.7, bias=0.0)
    F.ribbon([wrL, haL], [0.05, 0.048], INK, 1.6, bias=0.2); fingers(F, haL, (-0.5, -0.8, 0.3), 4, 0.07, 0.01, INK, 0.21)
    # 세검: 금 고리 손잡이 + 가는 흰 칼날 (뒤로 비스듬히)
    F.ribbon([(-0.37, 0.86, 0.08), (-0.52, 0.42, 0.22), (-0.66, 0.02, 0.36)], [0.024, 0.018, 0.004], PAPER, 1.3, shade=False, bias=0.08)
    F.line([(-0.33, 0.9, 0.12), (-0.4, 0.85, 0.15), (-0.41, 0.8, 0.12), (-0.35, 0.79, 0.08)], 2.4, GOLD, 0.09)
    F.ribbon([(-0.36, 0.95, 0.06), (-0.33, 0.86, 0.02), (-0.32, 0.74, 0.0)], [0.022, 0.016, 0.004], BLUE, 1.0, shade=False, bias=0.07)
    # 목 · 얼굴
    F.ribbon([(0.0, 1.47, 0.0), (0.004, 1.58, 0.01)], [0.06, 0.056], SKIN, 1.3, bias=0.0)
    face(F, hc, accent=BLUE)
    # 머리: 두개골 덩어리 + 앞머리 가닥 (한 가닥이 얼굴을 가로지름) + 옆머리 + 파랑 브리지 + 흰 하이라이트
    F.blob([(hc[0] - 0.105, 1.66, 0.0), (hc[0] - 0.09, 1.76, 0.02), (hc[0], 1.81, 0.02), (hc[0] + 0.09, 1.77, 0.02), (hc[0] + 0.108, 1.66, 0.0), (hc[0] + 0.08, 1.6, -0.05), (hc[0], 1.58, -0.09), (hc[0] - 0.08, 1.6, -0.05)], INK, 2.0, bias=0.02)
    for (x0, x1, y1, w) in [(-0.06, -0.09, 1.6, 0.07), (-0.03, -0.045, 1.63, 0.06), (0.0, 0.01, 1.6, 0.06), (0.03, 0.06, 1.645, 0.055), (0.07, 0.1, 1.58, 0.06)]:
        hair_strand(F, (hc[0] + x0 * 0.6, 1.8, 0.05), [(hc[0] + x0, 1.73, 0.1), (hc[0] + (x0 + x1) / 2, (1.73 + y1) / 2, 0.11), (hc[0] + x1, y1, 0.1)], w, bias=0.3)
    hair_strand(F, (hc[0] + 0.03, 1.79, 0.06), [(hc[0] + 0.0, 1.71, 0.11), (hc[0] - 0.035, 1.64, 0.105), (hc[0] - 0.06, 1.56, 0.09)], 0.05, bias=0.31)   # 얼굴을 가로지르는 가닥
    for s in (-1, 1):
        hair_strand(F, (hc[0] + s * 0.1, 1.72, 0.02), [(hc[0] + s * 0.12, 1.62, 0.05), (hc[0] + s * 0.14, 1.5, 0.04), (hc[0] + s * 0.165, 1.4, 0.02)], 0.075, bias=0.2)
    hair_strand(F, (hc[0] + 0.1, 1.7, 0.03), [(hc[0] + 0.125, 1.6, 0.06), (hc[0] + 0.15, 1.5, 0.05), (hc[0] + 0.19, 1.42, 0.03)], 0.04, BLUE, bias=0.25, sw=1.0)
    hair_strand(F, (hc[0] + 0.085, 1.74, 0.04), [(hc[0] + 0.11, 1.66, 0.075), (hc[0] + 0.12, 1.58, 0.07)], 0.03, BLUE, bias=0.32, sw=1.0)
    F.line([(hc[0] - 0.06, 1.775, 0.07), (hc[0] - 0.01, 1.795, 0.08), (hc[0] + 0.04, 1.785, 0.075)], 2.2, HI, 0.33); F.line([(hc[0] - 0.085, 1.72, 0.06), (hc[0] - 0.07, 1.75, 0.07)], 1.6, HI, 0.33)
    return J

# --------------------------------------------------------------------------- 대검 (적)
def great(F):
    J, h = body_joints(1.86, 7.8, 0.18, 0.13, 'L')
    hc = (-0.01, 1.71, 0.0)
    # 높게 묶은 꼬리머리 (뒤 · 길게 · 빨강 한 가닥)
    hair_strand(F, (hc[0], 1.86, -0.07), [(hc[0] + 0.06, 1.9, -0.16), (hc[0] + 0.16, 1.72, -0.24), (hc[0] + 0.24, 1.45, -0.26), (hc[0] + 0.36, 1.18, -0.24)], 0.13, bias=-0.6)
    hair_strand(F, (hc[0] + 0.02, 1.86, -0.08), [(hc[0] + 0.1, 1.86, -0.18), (hc[0] + 0.22, 1.66, -0.25), (hc[0] + 0.32, 1.4, -0.26)], 0.04, RED, bias=-0.55, sw=1.0)
    hair_strand(F, (hc[0] - 0.01, 1.85, -0.07), [(hc[0] + 0.02, 1.82, -0.17), (hc[0] + 0.08, 1.6, -0.24), (hc[0] + 0.12, 1.34, -0.25)], 0.07, bias=-0.58)
    # 흰 긴 코트 뒷자락 (발목까지 · 갈라진 끝 · 바람)
    F.blob([J['shL'], (0.22, 1.2, -0.08), (0.26, 0.8, -0.1), (0.33, 0.3, -0.12), (0.36, 0.1, -0.13), (0.25, 0.14, -0.13), (0.16, 0.06, -0.13), (0.06, 0.13, -0.13), (-0.05, 0.06, -0.13), (-0.14, 0.14, -0.12), (-0.24, 0.1, -0.12), (-0.25, 0.4, -0.11), (-0.23, 0.9, -0.09), (-0.2, 1.2, -0.08), J['shR']],
           PAPER, 2.2, bias=-0.5, smooth=False, shade_pts=[(0.0, 1.3, -0.1), (0.1, 0.8, -0.12), (0.06, 0.13, -0.13), (0.16, 0.06, -0.13), (0.25, 0.14, -0.13), (0.36, 0.1, -0.13), (0.33, 0.3, -0.12), (0.26, 0.8, -0.1), (0.22, 1.2, -0.08), J['shL']])
    # 넓은 검정 하의 + 무거운 부츠
    for s in 'RL':
        F.ribbon([J['hip' + s], J['kn' + s]], [0.15, 0.1], INK, 2.0, bias=-0.05)
        F.ribbon([J['kn' + s], lerp(J['kn' + s], J['an' + s], 0.5), J['an' + s]], [0.1, 0.095, 0.07], INK, 2.0, bias=-0.05)
        F.ribbon([J['an' + s], J['toe' + s]], [0.085, 0.03], INK, 1.8, bias=0.0)
    # 검정 속옷 몸통 (목 높음)
    F.blob([(-0.05, 1.6, 0.04), J['shR'], (-0.15, 1.38, 0.03), (-0.11, 1.12, 0.06), (-0.14, 0.98, 0.05), (0.0, 0.9, 0.08), (0.15, 0.98, 0.05), (0.12, 1.12, 0.06), (0.15, 1.38, 0.03), J['shL'], (0.05, 1.6, 0.04)], INK, 1.8, bias=0.0)
    # 빨강 허리띠 + 늘어진 끝
    F.ribbon([(-0.12, 1.04, 0.08), (0.0, 1.03, 0.11), (0.125, 1.04, 0.08)], [0.06, 0.06, 0.06], RED, 1.4, shade=False, bias=0.12)
    F.ribbon([(0.1, 1.02, 0.1), (0.15, 0.86, 0.12), (0.17, 0.66, 0.11)], [0.04, 0.032, 0.008], RED, 1.2, shade=False, bias=0.14)
    F.ribbon([(0.08, 1.02, 0.1), (0.1, 0.84, 0.13), (0.09, 0.62, 0.13)], [0.035, 0.03, 0.006], RED, 1.2, shade=False, bias=0.14)
    # 흰 긴 코트 앞판 (무게로 늘어진 천 · 큰 꺾임)
    F.blob([(0.05, 1.6, 0.06), J['shL'], (0.22, 1.36, 0.04), (0.2, 1.1, 0.08), (0.24, 0.7, 0.12), (0.3, 0.2, 0.12), (0.2, 0.1, 0.14), (0.14, 0.16, 0.15), (0.1, 0.6, 0.15), (0.085, 1.0, 0.13), (0.07, 1.36, 0.11)],
           PAPER, 2.2, bias=0.15, smooth=False, shade_pts=[(0.15, 1.3, 0.09), (0.17, 1.0, 0.11), (0.19, 0.6, 0.13), (0.24, 0.16, 0.13), (0.3, 0.2, 0.12), (0.24, 0.7, 0.12), (0.2, 1.1, 0.08), (0.22, 1.36, 0.04)])
    F.blob([(-0.05, 1.6, 0.06), J['shR'], (-0.21, 1.36, 0.04), (-0.19, 1.1, 0.08), (-0.25, 0.7, 0.12), (-0.33, 0.22, 0.12), (-0.24, 0.12, 0.14), (-0.16, 0.18, 0.15), (-0.1, 0.6, 0.15), (-0.08, 1.0, 0.13), (-0.065, 1.36, 0.11)],
           PAPER, 2.2, bias=0.15, smooth=False, shade_pts=[(-0.1, 0.6, 0.15), (-0.16, 0.18, 0.15), (-0.2, 0.15, 0.145), (-0.14, 0.6, 0.15), (-0.12, 1.0, 0.13)])
    F.line([(0.17, 0.95, 0.12), (0.2, 0.62, 0.13)], 0.9, INK, 0.2); F.line([(-0.17, 0.85, 0.13), (-0.21, 0.48, 0.13)], 0.9, INK, 0.2); F.line([(0.21, 0.5, 0.13), (0.26, 0.26, 0.13)], 0.9, INK, 0.2)
    F.blob([(-0.07, 1.54, 0.04), (-0.065, 1.66, 0.04), (0.0, 1.62, 0.07), (0.065, 1.66, 0.04), (0.07, 1.54, 0.04), (0.0, 1.5, 0.09)], INK, 1.6, bias=0.2, smooth=False)
    # 넓은 흰 소매 · 검정 장갑. 오른손은 대검을 어깨에 걸침, 왼손은 늘어뜨림
    elR, wrR = (-0.26, 1.22, 0.06), (-0.16, 1.36, 0.2)
    F.ribbon([J['shR'], elR, wrR], [0.13, 0.12, 0.15], PAPER, 1.8, bias=0.2)
    F.ribbon([wrR, (-0.13, 1.39, 0.22), (-0.115, 1.42, 0.23)], [0.06, 0.055, 0.02], INK, 1.6, bias=0.32)
    elL, wrL = (0.27, 1.13, -0.04), (0.27, 0.86, 0.04)
    F.ribbon([J['shL'], elL, wrL], [0.13, 0.12, 0.16], PAPER, 1.8, bias=0.02)
    F.ribbon([wrL, (0.28, 0.79, 0.06)], [0.06, 0.056], INK, 1.6, bias=0.03); fingers(F, (0.28, 0.79, 0.06), (0.05, -1.0, 0.2), 4, 0.08, 0.012, INK, 0.04)
    # 대검: 어깨에 걸친 큰 검정 날 (대각선) + 흰 날 선 + 금 코등이 + 빨강 손잡이 · 술
    grip0, grip1 = (-0.08, 1.30, 0.26), (-0.15, 1.42, 0.22)
    F.ribbon([grip0, grip1], [0.04, 0.04], RED, 1.3, shade=False, bias=0.34)
    guard = (-0.18, 1.47, 0.2)
    F.ribbon([(-0.24, 1.42, 0.24), guard, (-0.12, 1.52, 0.16)], [0.03, 0.035, 0.03], GOLD, 1.3, shade=False, bias=0.35)
    F.ribbon([guard, (-0.28, 1.66, 0.05), (-0.38, 1.86, -0.1), (-0.46, 2.02, -0.22)], [0.12, 0.13, 0.13, 0.015], INK, 2.2, shade=False, bias=-0.15)
    F.line([(-0.2, 1.52, 0.17), (-0.33, 1.76, -0.02), (-0.43, 1.96, -0.18)], 1.6, PAPER, -0.14)
    F.ribbon([(-0.06, 1.28, 0.27), (-0.04, 1.16, 0.28), (-0.06, 1.02, 0.27)], [0.03, 0.024, 0.006], RED, 1.0, shade=False, bias=0.36)
    # 목 · 얼굴 (빨강 눈가 선)
    F.ribbon([(0.0, 1.52, 0.0), (0.0, 1.63, 0.01)], [0.065, 0.06], SKIN, 1.3, bias=0.0)
    face(F, hc, accent=RED, accentY=-0.03, brows=True)
    # 넘긴 머리: 두개골 덩어리 + 뒤로 넘긴 가닥 + 이마로 떨어지는 몇 가닥
    F.blob([(hc[0] - 0.105, 1.71, -0.01), (hc[0] - 0.085, 1.82, 0.02), (hc[0], 1.865, 0.02), (hc[0] + 0.085, 1.82, 0.02), (hc[0] + 0.105, 1.71, -0.01), (hc[0] + 0.08, 1.66, -0.06), (hc[0], 1.64, -0.1), (hc[0] - 0.08, 1.66, -0.06)], INK, 2.0, bias=0.02)
    for (x0, x1, y1, w) in [(-0.05, -0.08, 1.7, 0.06), (0.0, -0.02, 1.72, 0.05), (0.04, 0.07, 1.69, 0.05)]:
        hair_strand(F, (hc[0] + x0 * 0.5, 1.86, 0.05), [(hc[0] + x0, 1.8, 0.1), (hc[0] + x1, y1, 0.105)], w, bias=0.3)
    for s in (-1, 1):
        hair_strand(F, (hc[0] + s * 0.1, 1.78, 0.0), [(hc[0] + s * 0.115, 1.68, 0.04), (hc[0] + s * 0.12, 1.58, 0.03)], 0.06, bias=0.2)
    F.line([(hc[0] - 0.06, 1.835, 0.07), (hc[0], 1.855, 0.08), (hc[0] + 0.05, 1.84, 0.07)], 2.2, HI, 0.33)
    return J

# --------------------------------------------------------------------------- 애저 워든: 선 흰 담비형 수호자 (S자 몸 · 작은 머리 · 긴 주둥이 · 둥근 귀 · 붉은 실눈 · 검정 꼬리 끝)
def fingers(F, base, d, n=4, L=0.07, spread=0.012, col=INK, bias=0.0):
    for k in range(n):
        o = (k - (n - 1) / 2) * spread
        F.ribbon([base, add(base, (d[0] * L * 0.5 + o, d[1] * L * 0.5, d[2] * L * 0.5)), add(base, (d[0] * L + o * 1.6, d[1] * L, d[2] * L))], [0.016, 0.013, 0.0], col, 1.0, shade=False, bias=bias)

def warden(F):
    rng = F.rng
    # 꼬리 (뒤에서 크게 S로 휘어 오름 · 끝 검정)
    F.ribbon([(0.0, 0.95, -0.35), (0.3, 0.5, -0.7), (0.72, 0.55, -0.62), (0.9, 1.0, -0.42)], [0.26, 0.3, 0.27, 0.22], PAPER, 2.2, bias=-1.0, n=7)
    F.ribbon([(0.9, 1.0, -0.42), (0.88, 1.25, -0.32), (0.76, 1.52, -0.22)], [0.22, 0.2, 0.0], INK, 2.2, shade=False, bias=-0.98)
    # 뒷다리: 넓게 웅크린 허벅지 + 뒤로 꺾인 아랫다리 + 검정 발톱
    for s in (-1, 1):
        F.blob([(s * 0.16, 1.08, -0.1), (s * 0.42, 1.0, -0.06), (s * 0.48, 0.72, 0.02), (s * 0.38, 0.5, 0.1), (s * 0.2, 0.55, 0.12), (s * 0.12, 0.8, 0.05)], PAPER, 2.2, bias=-0.25, jag=3,
               shade_pts=[(s * 0.34, 0.9, 0.0), (s * 0.42, 1.0, -0.06) if s > 0 else (s * 0.3, 0.6, 0.1), (s * 0.48, 0.72, 0.02), (s * 0.38, 0.5, 0.1), (s * 0.3, 0.62, 0.08)])
        F.ribbon([(s * 0.36, 0.52, 0.1), (s * 0.42, 0.28, -0.02), (s * 0.4, 0.07, 0.1)], [0.15, 0.1, 0.09], PAPER, 2.0, bias=-0.15)
        fingers(F, (s * 0.4, 0.06, 0.14), (s * 0.15, -0.3, 1.0), 3, 0.14, 0.035, INK, -0.1)
    # 몸: 엉덩이 → 배(앞) → 등이 굽은 가슴 → 앞으로 뻗은 목 (S자 · 사냥 자세)
    F.ribbon([(0.0, 0.92, -0.18), (0.0, 1.32, 0.04), (0.0, 1.74, -0.04), (0.0, 2.08, 0.12), (0.0, 2.3, 0.36)], [0.74, 0.64, 0.54, 0.34, 0.24], PAPER, 2.4, bias=-0.05, n=9)
    F.blob([(0.2, 1.7, 0.1), (0.3, 1.45, 0.12), (0.34, 1.15, 0.0), (0.26, 0.95, -0.08), (0.18, 1.2, 0.12), (0.12, 1.5, 0.16)], SH, 0, bias=-0.03, jag=4)
    F.blob([(0.1, 2.15, 0.25), (0.16, 1.98, 0.14), (0.2, 1.82, 0.05), (0.1, 1.9, 0.12)], SH, 0, bias=-0.02, jag=2)
    for i in range(5):
        y = 1.12 + i * 0.1; F.line([(-0.2 + rng.random() * 0.04, y, 0.24), (-0.13, y - 0.03 - rng.random() * 0.03, 0.27), (-0.17 + rng.random() * 0.05, y - 0.07, 0.26)], 1.3, INK, 0.05)
    # 검정 망토 (어깨 · 찢긴 끝)
    F.blob([(-0.3, 1.98, -0.02), (-0.2, 2.16, 0.08), (0.0, 2.2, 0.2), (0.2, 2.16, 0.08), (0.3, 1.98, -0.02), (0.36, 1.66, -0.1), (0.28, 1.54, -0.06), (0.22, 1.66, 0.0), (0.15, 1.5, 0.02), (0.08, 1.64, 0.1), (0.0, 1.52, 0.14), (-0.09, 1.66, 0.1), (-0.16, 1.5, 0.04), (-0.23, 1.66, 0.0), (-0.3, 1.52, -0.06), (-0.37, 1.7, -0.1)], INK, 2.2, bias=0.05, smooth=False)
    # 앞발: 덮칠 듯 들어 올림 · 긴 검정 발톱 / 왼쪽 앞발에 검정 방패
    F.ribbon([(-0.24, 1.95, 0.05), (-0.52, 2.02, 0.2), (-0.58, 1.72, 0.48)], [0.19, 0.15, 0.13], PAPER, 2.0, bias=0.2)
    fingers(F, (-0.58, 1.68, 0.5), (-0.1, -0.7, 0.6), 4, 0.24, 0.03, INK, 0.25)
    F.ribbon([(0.24, 1.95, 0.05), (0.5, 1.96, 0.22), (0.5, 1.7, 0.48)], [0.19, 0.15, 0.13], PAPER, 2.0, bias=0.15)
    sc = (0.52, 1.72, 0.62)
    F.blob([add(sc, (0.0, 0.42, 0.0)), add(sc, (0.2, 0.28, -0.04)), add(sc, (0.25, 0.0, -0.06)), add(sc, (0.18, -0.32, -0.04)), add(sc, (0.0, -0.44, 0.0)), add(sc, (-0.18, -0.32, 0.04)), add(sc, (-0.23, 0.0, 0.06)), add(sc, (-0.18, 0.28, 0.04))], INK, 2.4, bias=0.5)
    F.blob([add(sc, (0.02 + 0.12 * math.cos(a), 0.02 + 0.12 * math.sin(a), 0.0)) for a in [i * math.pi / 6 for i in range(12)]], RED, 1.2, bias=0.51)
    F.line([add(sc, (-0.14, 0.27, 0.05)), add(sc, (-0.07, 0.33, 0.04)), add(sc, (-0.02, 0.25, 0.03))], 2.4, PAPER, 0.52)
    F.line([add(sc, (-0.16, -0.18, 0.05)), add(sc, (-0.05, -0.23, 0.04)), add(sc, (-0.09, -0.32, 0.04))], 2.2, PAPER, 0.52)
    # 머리 (작게 · 앞으로 낮게 · 긴 주둥이 · 작은 둥근 귀 · 붉은 실눈)
    hc = (0.0, 2.38, 0.5)
    F.blob([add(hc, (-0.13, 0.05, -0.08)), add(hc, (-0.1, 0.13, -0.04)), add(hc, (0.0, 0.15, 0.0)), add(hc, (0.1, 0.13, -0.04)), add(hc, (0.13, 0.05, -0.08)), add(hc, (0.1, -0.06, 0.06)), add(hc, (0.045, -0.1, 0.24)), add(hc, (0.0, -0.11, 0.3)), add(hc, (-0.045, -0.1, 0.24)), add(hc, (-0.1, -0.06, 0.06))], PAPER, 2.0, bias=0.7,
           shade_pts=[add(hc, (0.02, 0.0, 0.18)), add(hc, (0.1, 0.07, -0.02)), add(hc, (0.13, 0.05, -0.08)), add(hc, (0.1, -0.06, 0.06)), add(hc, (0.045, -0.1, 0.24))], jag=1.2)
